
INSERT OR REPLACE INTO findings (doc, title, date, verdict, summary) VALUES ('153', 'Flow-score v1 - the AuclairsDad book reverse-engineered (doc 84)', '2026-10-19', 'REJECTED', 'His engine as observable: score of HTF fast EMA, VWAP, levels, overnight session and order-flow DELTA (the input he names as decisive), with 1.5-ATR stop, half at +1 ATR, breakeven, trail. On 18 perps x 13 months of 5-minute bars with Binance taker buy/sell imbalance: every variant equals its random control (-0.04% vs -0.04%/ep); delta alone, delta+trend, score=5, Asia, US - all random. Exit-free barrier race 49-50% vs 50% for every delta threshold incl. z>3.5, absorption and exhaustion. The management reproduces his 59-67% win rate with PF 0.80: breakeven stops raise P(win), not expectancy. Limit: 5-minute taker ratio, not tick-level footprint delta; NQ overnight not tested. Cannot replicate with held data.');
INSERT OR REPLACE INTO findings (doc, title, date, verdict, summary) VALUES ('154', 'Golden-cross long v1 refinements (doc 84)', '2026-10-19', 'NOTED', 'On the registered bull+confirmed hold-18 stop-3 book (+1.11%/ep t=4.0, 78% coins): half off at +2 ATR + breakeven -> +0.66% (win 61%); ride ribbon cap 60 -> +1.62% but 35% win, 41-bar hold; 4-ATR trail -> +0.90%; above-EMA200 +1.25%; weekday-only +1.21%; ASIA-SESSION ENTRIES ONLY +1.49%/ep, edge +1.70, top-5% share 85% vs 120% - healthier tail, 40% of the trades. v2 candidate once v1 has 50 trades. v1 unchanged.');
INSERT OR REPLACE INTO rules (id, rule, why, doc, added) VALUES (164, 'A win rate produced by breakeven stops and partial targets is not evidence of edge; judge an imported strategy on expectancy vs a random control with the identical management, never on its win rate or profit factor alone', 'finding 153: his 67% win rate reproduced exactly on random entries', '84', '2026-10-19');
